// S6-B2：McpManager 构造/apply/路由装配是装配依赖，留包根；其余纯符号改道域门面。
const { apply, McpManager, McpMiddleware, makeHealthRoute } = await import("../../src/index.ts");
const { McpStore } = await import("../../src/server/store/interface.ts");
const {
  normalizeServer,
