  buildConfigUiPatch,
  panelTopForAnchor,
  SERVER_NAME_PATTERN,
  DEFAULT_UI_CONFIG,
  Config,
} = await import("../../src/server/config/interface.ts");
const {
  panelAnchorForPosition,
  Z_INDEX_BASE_MIN,
  Z_INDEX_BASE_MAX,
  panelZIndexFor,
  BREAKPOINT_NARROW_MAX,
