  it("缺省 toolCallTimeoutMs 为数字", () => {
    expect(typeof bare().toolCallTimeoutMs).toBe("number");
  });

  it("缺省 toolCallTimeoutMs 为正", () => {
    // normalizeServer 恒补齐默认超时（被测契约），此处断言存在。
    expect(bare().toolCallTimeoutMs! > 0).toBeTruthy();
