describe("isSecretEnvName 精确判定", () => {
  it("子串误伤回归：MONKEY / TURKEY_SIZE / KEYBOARD / AUTHOR_NAME 放行", () => {
    for (const name of ["MONKEY", "TURKEY_SIZE", "KEYBOARD", "AUTHOR_NAME", "TURKEY", "TURKEY2"]) {
