/**
 * dsh-mcp-manager connection/orchestrator 子层（连接编排）端口持有者 —— 三条装配守卫（#767 终态评审补测）。
 *
 * 判据面（这三条错误路径原先全仓零覆盖，是本域端口持有者上的存活变异体来源）：
 * 未装配时 `get()` 抛错而不是回落默认值、重复 `install()` 当场抛错、`release()` 复位装配
 * 标记。判词逐字取自 `impl/service/index.ts` 的 throw 实参——改坏即红。
 *
 * 装配/卸载走门面（`installOrchestrator`/`releaseOrchestrator`），只有 `get()` 直连持有者：门面不导出 `get()`，
 * 而 unit 层白盒直连 `src/server/<域>/impl/**` 是 I8 允许的。
 */
import { afterEach, describe, expect, it } from "vitest";
import type { OrchestratorDeps } from "../../../src/server/connection/orchestrator/deps.ts";
import { orchestratorPorts } from "../../../src/server/connection/orchestrator/impl/service/index.ts";
import {
  installOrchestrator,
  releaseOrchestrator,
} from "../../../src/server/connection/orchestrator/interface.ts";

/** 本用例只验装配守卫、不消费任何 Port 成员，故给最小对象字面量而非逐个成员造假体。 */
const deps = {} as OrchestratorDeps;

// 持有者是模块级单例：不复位会让「只能装配一次」连坐后续用例。
afterEach(() => {
  releaseOrchestrator();
});

describe("connection/orchestrator 子层端口持有者装配守卫", () => {
  it("未装配时 get() 抛错，判词指向组合根漏装 installOrchestrator", () => {
    expect(() => orchestratorPorts.get()).toThrow(
      /connection\/orchestrator 子层未装配——组合根未在入口调用 installOrchestrator/,
    );
  });

  it("重复 install() 当场抛错，且不换掉已装配的端口", () => {
    installOrchestrator(deps);

    expect(() => installOrchestrator(deps)).toThrow(/connection\/orchestrator 子层只能装配一次/);
    expect(orchestratorPorts.get()).toBe(deps);
  });

  it("release() 复位标记：get() 复归抛错，且可重新装配", () => {
    installOrchestrator(deps);
    releaseOrchestrator();

    expect(() => orchestratorPorts.get()).toThrow(/connection\/orchestrator 子层未装配/);
    expect(() => installOrchestrator(deps)).not.toThrow();
    expect(orchestratorPorts.get()).toBe(deps);
  });
});
